class Solution(object):
    def stoneGameII(self, piles):
        """
        :type piles: List[int]
        :rtype: int
        """
        n = len(piles)
        cur_sum = 0
        dp = [[0 for _ in range(n + 1)] for _ in range(n)]
        for i in range(n - 1, -1, -1):
            cur_sum += piles[i]
            for M in range(1, n + 1):
                if i + 2 * M >= n:
                    dp[i][M] = cur_sum
                else:
                    for x in range(1, 2 * M + 1):
                        dp[i][M] = max(dp[i][M], cur_sum - dp[i + x][max(M, x)])
        return dp[0][1]

